import { releaseLog } from "./release-log";

export type EditorRelease = { version:string; title:string; changes:readonly string[] };

const recent:EditorRelease[]=[
  {version:"v1.14.4",title:"Preserved cut geometry and consistent editor controls",changes:["Excluded SVG clipping masks from editable geometry and bypassed Boolean imports for untouched vector previews.","Moderately adjusted Smooth curve fitting while retaining topology, silhouette and small-piece validation.","Standardized modal control, button and help typography with a 9px minimum help size and larger primary cut tools.","Added a fading tool-selection reminder, pixel-exact eyedrop magnifier, consistent background history buttons and an accent Advanced Removal action."]},
  {version:"v1.14.3",title:"Local vector editing and post-edit gap filling",changes:["Applied brush add/erase as vector Boolean operations; edge repair replaces only the brushed region without refitting unaffected curves.","Resolved relative SVG subpath origins for post-edit Fill Gaps and retained direct curve inspection for relative commands.","Kept native vectors through preview, Apply Edit, frame updates and separation; disabled the gap slider when Fill All is checked.","Improved brush roundness and constant screen outline, readable tool icons, consistent modal history controls and picked-color button text.","Preserved selected existing layer IDs through undo/redo and moved Bake Cutout beside the vector Add Outline action."]},
  {version:"v1.14.2",title:"Responsive vector gap filling",changes:["Replaced repeated path-length traversal with direct adaptive Bezier inspection for generated Cut Shapes, retaining original SVG commands verbatim.","Filtered containment by bounds and reused nesting results rather than repeating polygon scans.","Made gap filling cooperative so long operations yield to browser input and rendering; bounded sampling remains available for other SVG commands."]},
  {version:"v1.14.1",title:"Vector-only gap filling",changes:["Fill Gaps and Fill All remove only enclosed vector subpaths without rasterizing or refitting the outer contour.","Retained original curve commands, viewport, layer placement and size; repeated fills use the pre-fill vector snapshot.","Making gap fills permanent now preserves the existing SVG rather than retracing it."]},
  {version:"v1.14",title:"Preview touchpad navigation and background removal controls",changes:["Confined pinch zoom and two-finger pan to modal previews, including native Safari gestures.","Added explicit picked-color rows up to three, with independent sensitivity controls and a single initial row.","Updated connected brush defaults to 3%, bleed 20 and Full reach; new removal sessions start with edge refine +3px and smoothing 5 while saved adjustments remain intact.","Calibrated creation contour smoothing against original foreground area, preserving topology safeguards."]},
  {version:"v1.13.8",title:"Balanced Smooth and Detailed contour quality",changes:["Shared contour noise cleanup across both raster creation modes, retaining true corners, extrema and tiny detached contours.","Removed pixel-step noise before fitting and kept a fixed subpixel contour complexity floor through tighter retries.","Adjusted Smooth to retain more shape variation and Detailed to retain finer usable curves without reproducing every raster sample.","Added relative complexity guidance and balanced Detailed recovery through the same clean curve family as Smooth, retaining topology and silhouette checks."]},
  {version:"v1.13.7",title:"Adaptive Cut Shape fitting and outline controls",changes:["Restored the initial Add Outline action to 0.4 cm independently of the selected-layer draft value.","Kept Edit Cut Shape in the second toolbar row and added a full-width action below a divider in the floating Cut Shape panel.","Quadrupled curve budgets after failed contour validation and progressively relaxed simplification rather than aborting difficult text conversions.","Added a lossless exposed-boundary SVG fallback preserving all pixels, pieces and counters without artificial internal cutting lines."]},
  {version:"v1.13.6",title:"Curve-aware raster contours and preserved alpha coverage",changes:["Preserved fractional alpha through background cleanup and Optimize Alpha instead of repeatedly binarizing the edge; kept fully opaque frames and translucent interiors unchanged.","Fitted bounded-error cubic curves directly to image contours, retaining true corners and extrema instead of exporting individual pixel steps.","Validated simplified SVG pieces, holes and silhouette deviation before accepting a conversion, with progressive retries and self-intersection checks.","Applied the creation-edge treatment to imported transparent images while leaving native SVG, edit preview, weld and separation tracing paths unchanged."]},
  {version:"v1.13.5",title:"Safe Cut Shape preview and optimized creation contours",changes:["Fixed bundled preview worker URLs resolving against a file origin and isolated preview worker errors from the editor.","Separated Detailed and Smooth creation profiles, reduced redundant curve nodes, and guarded silhouette cleanup against losing detached pieces or enclosed holes.","Kept existing editing, weld and separation tracing tolerances unchanged; preserved the creation viewport while tracing with an external safety margin."]},
  {version:"v1.13.4",title:"Crisp vector Cut Shape display",changes:["Rendered original Cut Shape SVG contours inline as vector geometry instead of displaying a scaled PNG, with zoom-compensated one-screen-pixel contour strokes.","Kept edit calculations and fast raster feedback separate from the displayed SVG; prepared post-edit display vectors in a dedicated worker without modifying stored paths or placement.","Preserved Separate as Layers through the full-quality geometry path rather than feeding it the display-only preview.","Shortened the welcome-splash upload and generation instruction and reduced the empty-design card surface and shadow opacity."]},

  {version:"v1.13.3",title:"Responsive Cut Shape editing with stable framing",changes:["Removed full SVG retracing and the debounce delay from every brush edit; vector generation now runs only when edits are accepted.","Kept one fixed transparent editing surface and one image scale from opening through all brush interventions.","Corrected expanded-surface edge-selection coordinates and serialized red overlay calculations to prevent stale feedback after repeated Fix the Edges strokes.","Recomputed final bounds only on Apply Edit and translated the trimmed origin back into page coordinates to preserve placement.","Updated the first welcome-splash instruction to explain computer uploads and new text or image generation."]},

  {version:"v1.13.2",title:"Persistent outline sources and Cut Shape feedback",changes:["Recomputed every Apply Outline update from the parent printable image including its outermost editable sticker border.","Restored red selection and green completion feedback while using Fix the Edges.","Kept the Cut Shape preview at a fixed visual position and scale while its editable transparent frame expands.","Replaced the safe-area footer message with the latest successful autosave time after autosave completes.","Refined three-line Add and Remove controls, reduced Safe Area labels sharply below fifty-percent zoom, placed Sticker Offset values inline and increased editor tool labels."]},

  {version:"v1.13.1",title:"Cut Shape precision and creation layout polish",changes:["Unified Edit Cut Shape brush and cursor coordinates across the expanded work area and kept their displayed diameters consistent after edits.","Added protected raster workspace around generated outlines so curved edges are traced before the final frame is established instead of being flattened at canvas boundaries.","Calculated printable-image Cut Shape outlines from the full rendered sticker-border result without baking or discarding its editable border settings.","Reformatted Add Line and Remove Line into narrow three-row actions and matched the image example height to its prompt column.","Normalized Sticker Offset rows with every other Edit History row and harmonized typography and controls across image and Cut Shape dialogs."]},

  {version:"v1.13",title:"Expanded Cut Shape editing and clearer settings",changes:["Added a true ten-percent transparent work margin around Cut Shapes so Add, Erase and Fix the Edges can operate beyond the original artwork boundary without flattening edge curves.","Kept brush coordinates and previews consistent before and after the first edit, while preserving the expanded geometry when edits are applied.","Aligned Edit Cut Shape Undo and Reset as matching rectangular header actions.","Added breathing room between the floating Cut Shape controls and the right sidebar.","Renamed Broken White to Off-White and added compact current-value summaries to every Settings category.","Added a dedicated ruler-origin square and stopped both rulers cleanly at that shared corner."]},

  {version:"v1.12.2",title:"Targeted workspace regression fixes",changes:["Locked the empty-canvas card, content and buttons to constant screen dimensions and removed the opaque blur while retaining a ten-percent panel surface.","Restored a visible high-contrast insertion line between layer cards during drag reorder.","Returned Cut Shape properties to a fixed position immediately left of the right sidebar.","Overrode generic Settings hover fill inside the custom page-colour palette so swatches keep their true colour and receive only an outline." ]},

  {version:"v1.12.1",title:"Workspace alignment and editor control corrections",changes:["Moved the layer edit-history chevron immediately left of the drag handle.","Kept the empty-canvas card and its controls at a constant screen size and reduced only its panel surface to ten-percent opacity.","Restored horizontal and vertical rulers to the workspace top and left edges without overlapping the right sidebar.","Changed page-colour hover feedback to an outline that no longer masks the colour swatch.","Realigned Apply Border, compacted Add/Remove Offset, and repaired Edit Cut Shape Undo/Reset controls.","Compacted Edit History to four visible rows and automatically kept the newest edit visible at the bottom.","Raised and constrained the Cut Shape floating panel so it remains inside the workspace beside the right sidebar." ]},

  {version:"v1.12",title:"Layered borders and a calmer creation workspace",changes:["Enlarged creation thumbnails, aligned image prompts and unified the primary creation actions.","Moved line controls into a compact left column and simplified Extra Prompt.","Added clearer Edit History presentation, compact layer cards and visible drag insertion markers.","Added persistent custom page colours and moved Control to the end of Settings.","Improved the new-project confirmation, zoom-resilient empty state, outside-page marquee, Safe Area label and Export As controls.","Added up to three independently editable sticker borders with backward-compatible storage, preview, bake and PNG export.","Recontained the rulers within the workspace and kept the right sidebar above all page chrome." ]},

  {version:"v1.11",title:"Resilient sidebar and accessible edit histories",changes:["Enlarged AI Archive item names and timestamps and constrained generated assets to compact chronological grid rows.","Hardened the editor workspace grid and right sidebar sizing so Size, Layer Properties and Layers cannot collapse or be covered by the page rulers.","Clipped the persistent horizontal ruler exactly where the right sidebar begins.","Changed each Layers-card edit history into a closed-by-default chevron disclosure with clipped, single-line child rows.","Restored an always-visible Layer Properties edit list with room for four rows and internal chronological scrolling beyond that limit.","Added balanced padding and spacing to Size and Layer Properties while retaining the wider right sidebar.","Removed side gutters from the Remove Background preset layout and fitted larger preview artwork to each full-width card.","Corrected the Sticker Border footer action so its full label stays aligned and contained at the lower-right.","Reduced Full Screen controls to icon-only buttons and switched to a distinct Minimize icon while expanded.","Increased Undo, Reset, footer action and modal control icon legibility."]},
  {version:"v1.10",title:"Input-aware navigation and unified editor controls",changes:["Added a persistent Control category to Settings with Touchpad as the default and an optional Mouse mode.","Kept two-finger Touchpad movement as canvas pan and pinch as zoom; made Mouse wheel zoom directly and Ctrl+wheel scroll the workspace.","Corrected the Add New Image OpenAI mark to use the supplied logo in green with a clear diagonal Sparkles composition.","Removed the unused lower archive void by making the creations grid consume the available dialog height and anchoring actions at the bottom.","Stopped the horizontal ruler at the right sidebar and raised the sidebar above the workspace rulers.","Moved Layer Edits back beneath each corresponding Layers card, removed the changes counter and exposed readable single-line edit entries without an additional collapsible nest.","Expanded the Remove Background chooser, preview artwork and typography for clearer preset selection.","Placed Separate as Layers at the lower-left in both image and Cut Shape editors and positioned Smooth immediately beside it in Cut Shape.","Added consistent header Undo and Reset controls to the editing workflow.","Added a Full Screen toggle beside the close control in Edit Image and Edit Cut Shape, preserving modal padding and allowing instant restoration."]},
  {version:"v1.09",title:"Centralized layer history and polished creation controls",changes:["Combined Layer Properties type and format into one icon-led Printable Image or Cut Shape identity.","Moved editable layer history out of layer cards and into a collapsible Layer Properties section with a four-row scrolling viewport that follows the latest change.","Preserved chained history removal so deleting an earlier edit also removes every dependent edit after it.","Added the editable Outline control to bare SVG Cut Shapes at 0.0 cm, displayed the active unit beside its value and aligned Remove left of Apply Outline.","Renamed the left navigation entry to AI Archive and rebuilt the archive footer with a large Create your own Text / Image action plus Close at the bottom-right.","Used the supplied OpenAI SVG logo alongside Sparkles in the Add New Image creation card and enforced a balanced two-card source layout.","Changed the active Remove Background treatment from solid green to a subtle pale-green action state.","Widened the right sidebar and increased Size and Layer Properties spacing and text legibility.","Added a subtle green unsaved-change indicator inside the project-name field.","Removed the malformed visible line-break token from the Add New Image source cards."]},
  {version:"v1.08",title:"Alpha-aware background removal guidance",changes:["Made Remove Background the green primary action whenever a selected JPG or PNG has no transparent pixels.","Kept Add Sticker Border to Image visibly disabled until real transparent pixels exist and removed primary emphasis from Add Outline while a background remains.","Applied a 500 px Remove Speckles cleanup automatically with the text background-removal preset.","Renamed the three background presets and replaced their generic subtitles with plain-English descriptions of outside removal, rim-preserving removal and inside/outside text cleanup.","Rebuilt checkerboard previews with an axis-aligned square pattern instead of the incorrect diamond appearance.","Increased left-rail label sizes for readability.","Restyled Layer Properties as a square white section divided by horizontal rules directly beneath Size.","Added breathing room along the right edge and realigned Settings toward the far left of its row.","Moved the Redo icon to the right of its label."]},
  {version:"v1.07",title:"Strict contextual tools and polished image editing controls",changes:["Removed the duplicate Add Sticker Border and Add Outline actions from the second toolbar row so both live only in the primary workflow row.","Made Bake Cutout render only for a selected Cut Shape and Image on Shape render only for a selected editor-created shape.","Moved Layer Properties visually against Size and removed the hidden legacy Stroke block that left an empty gap.","Matched Redo dimensions and responsive behaviour to Undo.","Restyled Show Alpha Channel as a real checkbox and separated Undo/Reset on the left from Alpha/Optimize Alpha on the right.","Disabled Create Layer until the current Edit Image session contains an actual edit.","Widened the left tool rail and enlarged its controls while preserving the editor grid alignment.","Rebuilt the Add New Image choice view with larger, balanced source cards and a combined upload icon plus an OpenAI-inspired knot mark.","Added a top-right chevron to collapse the Cut Shape properties panel into a single header row.","Matched Apply Outline and Apply Fill sizing, emphasis and right alignment.","Kept primary workflow actions visible in a clearly disabled state when no layer is selected."]},
  {version:"v1.06",title:"Clear printable-image actions and editable output properties",changes:["Removed Color, Image on Shape and Bake Cutout from Printable Image selections while keeping shape and Cut Shape tools context-sensitive.","Moved Add Sticker Border to Image and Add Outline as Cut Shape into the primary top action row with explicit names.","Added a background check before Sticker Border and a clear route into Background Removal when the image has no transparent pixels.","Stopped the floating Cut Shape property panel from dismissing selection when its controls are clicked.","Replaced Fill all the gaps with a checkbox applied through the prominent Apply Fill action.","Renamed the outline action to Apply Outline, made Remove compact and reset its value when the outline is removed.","Added a Layer Properties card between Size and Layers showing type, format, readiness, style and editable-weld state.","Made raster, vector and mixed welds reversible until export by retaining source layers and exposing Unweld.","Renamed and reordered Add New Image choices, with Upload From Your Computer first and clearer combined source icons.","Renamed the Sticker Border editor and final action, expanded its full color palette, enlarged color picking and added a collapsible advanced color control.","Renamed Alpha controls to Show Alpha Channel and added a visible disabled-aware Redo action beside Undo."]},
  {version:"v1.05",title:"Guided Printable Image and Cut Shape workflow",changes:["Stored the stable v1.04 code state as the local backup branch backup/v1.04-before-guided-ui and annotated tag v1.04-stable before beginning the redesign.","Temporarily removed Make It Acetate from the visible interface while retaining its implementation and legacy-project compatibility.","Reorganized the first and second toolbar rows around context-sensitive next actions for Printable Images, Cut Shapes and multi-layer selections.","Renamed user-facing raster and vector layer states to Printable Image and Cut Shape, with source format and Background detected, Edge cleanup recommended or Ready guidance.","Added backward-compatible status analysis when older projects are opened and marked successful Background Removal results as ready transparent PNG artwork.","Made Add Outline on transparent raster artwork preserve the full-colour Printable Image and create an editable Cut Shape outline underneath it.","Directed solid-background artwork to Background Removal before Cut Shape creation and added a non-destructive edge-preparation choice between Clean Edges, Sticker Border and Continue Anyway.","Moved editable Outline and Fill Gaps controls into a compact floating Cut Shape panel at the upper-right of the page workspace.","Added Fill all the gaps, which fills every enclosed opening without expanding the exterior contour when the 30 mm threshold is insufficient.","Removed the duplicate Fill Gaps tab from normal Edit Cut Shape navigation and hid Background Removal and Sticker Offset duplicates from normal Edit Image navigation while preserving their dedicated entry points.","Added group-level hide/show and collapse/expand controls, persisting those states with project layers and respecting hidden groups in canvas, hit testing, thumbnails and PDF output.","Added Layers-panel double-click focus: the chosen layer is centred on the page workspace at exactly 100% zoom while layer-name double-click continues to rename." ]},
  {version:"v1.04",title:"Native trackpad navigation and persistent workspace settings",changes:["Changed ordinary two-finger trackpad scrolling to pan the editor canvas horizontally and vertically instead of changing zoom.","Reserved macOS trackpad pinch gestures for pointer-anchored zoom, keeping the artwork under the gesture stable while scaling.","Added a guaranteed 100% stop to toolbar and keyboard zoom steps when moving through the 91–109% range.","Persisted page size, orientation, units, page colour, grid visibility and safe-area settings in the browser.","Stopped New Project and Open Project from replacing the user's persistent workspace settings with A4 portrait and centimetre defaults or project-specific values." ]},
  {version:"v1.03",title:"Visible and namespace-safe vector Weld output",changes:["Preserved SVG mask, clipping, gradient, pattern and filter definitions while composing Weld output instead of recolouring their internal geometry.","Namespaced every imported SVG definition identifier and rewrote its local references, preventing masks from separate cutout components from overwriting one another.","Restricted Weld recolouring to visible artwork and retained genuine visible strokes, so separated cutout layers remain present on the canvas after welding." ]},
  {version:"v1.02",title:"Lossless multi-cutout weld and high-resolution cutout editing",changes:["Changed vector Weld grouping to test actual opaque artwork intersection instead of overlapping rectangular layer bounds, so nearby or interleaved but visually separate cutouts keep their original SVG paths exactly.","Kept non-touching members of large Weld selections as untouched native SVG components; only genuinely intersecting artwork is merged and retraced.","Moved SVG Edit Cutout processing to a high-resolution 3200-pixel working surface before Fix the Edges, Add Brush or Eraser operations, preventing low-resolution intermediate masks from creating stair-stepped contours.","Enabled high-quality image resampling throughout the cutout editing surface so brush results and regenerated curves remain clean at deep zoom levels." ]},
  {version:"v1.01",title:"True island separation, nested groups and raster weld",changes:["Corrected lossless Separate as Layers so each SVG viewBox is also constrained by its exact connected-component mask; neighboring artwork inside the same rectangular bounds can no longer leak into the separated layer.","Kept each separated island's original SVG paths underneath the isolation mask instead of smoothing or retracing its edges.","Added visible Photoshop-style Group headers to Layers and indented every member beneath its folder.","Made newly grouped layers contiguous in the layer stack and allowed a group member to be dragged onto an ungrouped layer or the dedicated outside drop area to remove it from the group.","Allowed Ctrl/Shift selection of individual members inside a group while ordinary selection continues to select and move the complete group; any selected subset moves through the shared multi-selection frame.","Extended Weld to raster and mixed selections, compositing them at source-aware high resolution into one transparent PNG layer and one PNG export.","Changed the primary save label to Save - Update after a project has a saved identity and disabled Save As until the first project save exists.","Made the project-name input visibly white with a stronger field boundary and focus state."]},
  {version:"v1.00",title:"Lossless SVG composition and precision workspace",changes:["Stopped Separate as Layers from rasterizing and retracing vector islands; separated SVG layers now retain the source paths and crop only their viewBox.","Rebuilt Weld as a hybrid operation: spatially separate cutouts are embedded with their original path geometry, while only genuinely overlapping clusters are union-traced.","Kept the full union selection frame visible while moving multiple cutouts so the selection does not collapse visually to the grabbed item.","Changed Layers reordering to a Photoshop-style stationary translucent drag card with a strong before/after insertion line and a single reorder on drop.","Added arrow-key nudging on the main canvas with zoom-aware precision, ranging from broader screen steps near 100% to one-screen-pixel steps at maximum zoom; Shift accelerates the movement.","Raised the main canvas maximum zoom from 700% to 900% across wheel, buttons, keyboard shortcuts and direct percentage entry.","Changed imported SVG files into Cutout layers directly, sanitizing and retaining their supplied vector markup without PNG conversion or automatic tracing.","Raised account capacity to 20 projects and 40 MB in the editor and database enforcement migration.","Enlarged Settings and category labels and gave selected and hovered choices distinct, higher-contrast states.","Disabled the low-resolution compositing hint in Edit Image so browser zoom re-rasterizes from the original full-resolution image source instead of enlarging a cached fitted preview."]},
  {version:"v0.99",title:"Raster paint repair and true alpha inspection",changes:["Repaired the Alpha control in the first Edit Image tab so it switches the actual working preview into a high-contrast black alpha silhouette over a neutral transparency grid.","Added independently toggleable Add Brush and Eraser tools to Edit Image while retaining Crop and Lasso Erase.","Made Add Brush paint the chosen solid colour into the raster and Eraser remove exactly the same brush footprint.","Added shared brush-size feedback, a visible diameter preview and 5–40% path smoothing for both raster brushes.","Corrected the raster overlay coordinate system and zoom translation so the cursor, live stroke and committed pixels remain aligned on non-square images.","Added a compact colour palette plus a collapsible Advanced colour editor with native picker, editable hex value and Pick Color from Image mode."]},
  {version:"v0.98",title:"Exact brush footprint and controlled smoothing",changes:["Unified the Edit Cutout cursor, control preview, live painted trail and committed mask around one physical brush diameter.","Removed independent display clamps that made the cursor look larger or smaller than the pixels actually affected.","Changed the live overlay from a stretched square coordinate system to the fitted artwork's real width and height so circular brushes no longer become wide ovals on non-square artwork.","Kept brush thickness visually stable through editor zoom while translating the same footprint into source-image pixels for the final edit.","Added path Smoothing only for Add Brush and Eraser Brush, defaulting to 5% and adjustable up to 40%.","Made Smoothing reduce hand jitter while preserving stroke endpoints and never changing the selected brush diameter."]},
  {version:"v0.97",title:"True inline Settings toolbar",changes:["Removed the floating Settings container, background, border, shadow and absolute toolbar positioning that obscured the canvas rulers.","Placed Settings and all six category controls in the normal toolbar flex flow as one continuous row.","Kept the Settings trigger chevron pointing right and every category chevron pointing down exactly as specified.","Kept only the selected category's choices as a conventional dropdown directly beneath its own button.","Removed the hidden centre toolbar from layout while Settings is open so the inline categories receive real space rather than floating over other controls."]},
  {version:"v0.96",title:"Conventional saving and refined creation workflows",changes:["Changed Save into a conventional direct action: the visible project name is saved immediately without unexpectedly opening My Projects, and subsequent renames update the same project.","Moved the Settings category strip onto the same toolbar row immediately to the right of Settings, with right-facing closed chevrons and downward-facing open chevrons.","Renamed My AI Gen to My Archive and My AI Generations to My Creations Archive, repaired its close control and added Create New at the bottom.","Replaced Number of lines with compact Add line and Remove line controls directly beneath the text inputs, retaining the one-to-four-line limit.","Made font and image-style cards select immediately and moved enlargement into a small dedicated expand icon on each preview.","Reduced image-style card height, tightened the image creation workspace and expanded Describe the image you want into a proper multiline prompt area.","Redesigned Create Sticker Offset to match the other Edit Image tabs, replacing the oversized white preset control with a compact colour palette, custom colour input and fitted Pick Color action.","Strengthened Separate as Layers actions across image and cutout editors so the operation is visually distinct.","Renamed Apply Preset to Background Removal Presets and made each preset render its real result in the fitted preview before the user accepts it.","Replaced the preset Back/Apply flow with Reset and Accept the result and Bring to Page, keeping changes non-destructive until acceptance.","Allowed Image on Shape source selection directly from canvas layers by removing the active shape selection overlay from the picking path.","Compacted preset and sticker previews to remove zoomed artwork, clipped control text and unused lower-page space." ]},
  {version:"v0.95",title:"Persistent creative library and exact sticker geometry",changes:["Added the editable project name beside the top Save controls so saving immediately uses the visible name and keeps the saved name in place.","Added readable Open and Overwrite labels to My Projects quick actions and made outside clicks dismiss the project window.","Kept the cached project index visible through browser minimize, token refresh and transient authentication events instead of clearing and reloading the list.","Combined saved-project count and cached total storage usage in My Account, updating the total only when project metadata changes.","Added My AI Gen above My Projects with separate Text and Image archives, generated names, timestamps, large previous/next preview, Add to Page and Delete controls.","Persisted every AI generation per signed-in user with a local instant cache and a row-secured Supabase archive migration.","Named AI canvas layers from their prompt using a compact title such as Cute Giraffe.. AI and kept generated text entering as a Cutout.","Made Connect Everything enabled by default for new text-generation sessions.","Rebuilt Settings as a left-aligned horizontal category strip whose individual menus open downward and close after a choice or outside click.","Replaced mismatched CSS sticker shadows with one shared high-quality raster offset used by the editor preview, canvas and PNG output.","Expanded Sticker Offset layer bounds equally on every side so pointed tips and edge-adjacent artwork are no longer clipped.","Added an editable Sticker Offset layer-style row with double-click reopening, correct naming and reliable removal that restores original geometry.","Made Bake Image appear only for a selected image with Sticker Offset and flatten that exact visual result into one transparent PNG.","Deduplicated Sticker Offset base and preview sources inside saved project assets to avoid inflating project JSON." ]},
  {version:"v0.94",title:"Production-safe Google sign-in redirect",changes:["Removed the Supabase OAuth redirect path that could fall back to the project's outdated localhost Site URL after sign-out.","Restored the nonce-protected Google Identity token exchange that creates the Supabase session directly on the current production page.","Kept every editor entry action on the live Cake Topper Maker domain and added a clear fallback message directing users to the rendered Continue with Google control when the browser suppresses the account prompt."]},
  {version:"v0.93",title:"Production accounts, compact projects and fabrication workspace",changes:["Replaced the fragile Google One Tap-only entry path with Supabase OAuth redirect sign-in so fresh and incognito browser sessions can reach the editor reliably.","Renamed Page Setup to Settings and added A4, US Letter, A5 and Large Canvas sizes with portrait and landscape controls.","Added centimetre and inch display/input units while retaining centimetres internally for stable physical geometry.","Added Group and Ungroup to both the top workspace toolbar and Layers actions, including mixed raster/vector groups that select and transform together.","Added Weld for multiple vector cutouts, producing one unioned SVG layer in world coordinates and using the topmost selected cutout colour.","Standardized generated vector sources as fill-only artwork and kept the single dark contour exclusively in the zoom-independent preview pipeline.","Matched the live Edit Cutout brush stroke and cursor diameter to the committed brush footprint at every editor zoom.","Added Create Sticker Offset as a fourth Edit Image tab with millimetre width, white preset, colour selector, screen colour picker, editable removal and live preview.","Stored Sticker Offset as a non-destructive layer style and baked it with the original artwork into one supersampled transparent PNG during export.","Changed AI generation progress from a spinning action icon to an animated pending-version card in the correct Text or Image Versions rail.","Packed repeated project image sources into a deduplicated asset table inside saved project data so operation snapshots no longer duplicate the same base64 payload.","Added lightweight project index fields for thumbnail, byte size, layer count and autosave status, with backward-compatible loading for the previous database schema.","Cached the project index per signed-in user so reopening My Projects after minimizing the browser shows known projects immediately while cloud metadata refreshes.","Added a five-minute dirty-project autosave that updates one recovery project, converts to a regular project on manual save and reports progress at the top of the editor.","Added server-ready enforcement for a maximum of 10 regular projects and 20 MB total project storage, allowing the first over-limit save to finish before blocking later saves.","Added total project storage usage beside the project count in My Account and retained delete/open access while saving is blocked.","Updated PDF output to use the selected A4, Letter, A5 or Large Canvas page and orientation.","Added a Supabase migration that backfills lightweight metadata and enforces project-count/storage limits at the database boundary." ]},
  {version:"v0.92",title:"Balanced Bézier contours and true vector edge previews",changes:["Replaced the shadow-based Cutout border with a display-only SVG contour applied directly to vector paths.","Removed the erroneous shadow around the complete Edit Cutout image canvas while retaining a thin, crisp outline around the artwork itself.","Kept the preview contour at a constant screen-pixel width at every zoom level without adding it to exported cutting geometry.","Rebalanced transparent-mask tracing to preserve round letterform curves while merging redundant neighboring Bézier control points.","Changed newly generated Stroke Cutouts to the same balanced Potrace curve profile instead of the highly fragmented VTracer output.","Applied balanced curve simplification to Bridge, Eraser and Fix the Edges results after each completed edit and again at Apply Edit.","Kept frame-preserving tracing for edited Stroke Cutouts so simplification does not narrow the layer or deform its physical bounds.","Removed visual edge strokes from exported SVG data so Cricut receives fill-only cutting paths." ]},
  {version:"v0.91",title:"Precision text cutouts and non-invasive vector editing",changes:["Made AI-generated text enter the canvas directly as a ready-to-edit vector Cutout instead of requiring a separate conversion step.","Increased transparent-artwork trace resolution and curve fidelity so rounded letterforms retain smooth Bézier contours instead of becoming short flat segments.","Stopped Apply Edit from automatically trimming transparent margins and shrinking a layer when Crop Canvas was not used.","Preserved the exact requested crop rectangle without performing a second content-based trim.","Made Apply Edit retain an untouched source exactly and use frame-preserving precision tracing only when an edit or explicit crop exists.","Unified Edit Cutout brush math so the cursor, live stroke, selected region and committed result use the same zoom-adjusted diameter.","Added a smooth one-screen-pixel, zoom-independent contour indicator to every Cutout and Stroke layer on both the canvas and initial Edit Cutout preview.","Balanced short text lines by enlarging them relative to much longer lines without forcing equal widths.","Added Connect Everything to request one physically connected lettering silhouette with bridges no thinner than 10 px / approximately 1 mm." ]},
  {version:"v0.90",title:"Live OpenAI image generation",changes:["Replaced the prepared-image simulation with authenticated, live OpenAI image generation for both text and illustration workflows.","Kept the OpenAI API key exclusively on the server and required a valid Supabase user session before any paid generation request can run.","Added controlled server-side prompt construction for exact multiline topper text, font direction, optional lettering details, illustration style and white sticker offset.","Requested full-size 1024 × 1024 transparent PNG output with generous contour padding for safer downstream Cricut conversion.","Connected generated PNG results to separate Text and Image version histories, the large preview and the existing Add to Page importer.","Made Change fonts request a genuinely new font treatment while preserving the exact entered wording and layout.","Added visible generating, success and API-error states and recorded successful generations in Session Log." ]},
  {version:"v0.89",title:"Balanced creation layout and aligned onboarding",changes:["Removed the forced height beneath the text inputs by matching the reference preview to the three-line composition height.","Expanded every text input across its available column so the composition area no longer leaves an unexplained central void.","Restored true horizontal centering for the empty-canvas actions after the previous max-width rule had anchored the panel left of centre.","Aligned all splash-screen step numbers and descriptions to shared rows so wrapped wording remains visually level across the three cards.","Protected the two Create your own image reference thumbnails from flex shrinking while their assets load." ]},
  {version:"v0.88",title:"Professional creation studios and guided welcome",changes:["Redesigned Add New, Cake topper as text and Cake topper as image as larger, consistent professional workspaces with readable typography no smaller than 10 pt.","Moved the compact Number of lines control above the text reference artwork and changed its default to three lines.","Added adaptive Happy / Birthday / Sophia placeholders for three lines, Happy Birthday / Sophia for two lines and Happy Birthday Sophia for one line.","Kept line composition expandable to four inputs and made empty inputs count as omitted so the generated layout follows only completed lines.","Renamed the collapsed decorative instruction section to Extra Prompt while keeping exact topper text separate.","Enlarged Change fonts, Create Text Image, Create Image, Use this font/style and Add to Page actions and separated primary actions with distinct colours.","Rebuilt option-gallery arrows as compact circular controls that no longer consume excessive preview space.","Darkened and desaturated image-style card surfaces for clearer transparent artwork previews.","Made White sticker offset immediately show a clean white outline around every style thumbnail and its enlarged preview.","Separated generated text history from generated illustration history so each studio retains only its own Versions list.","Made long Versions lists independently scrollable without expanding the creation dialog.","Replaced the empty-canvas actions with Upload image from your Computer, Generate Your Own Image and Open Existing Project.","Added a dismissible Cake Topper Maker welcome screen with a three-step workflow, Start Now action and outside-click/close controls.","Stored Don't show this on Startup per signed-in user instead of applying one shared browser-wide preference." ]},
  {version:"v0.87",title:"Explicit text composition and browsable style previews",changes:["Replaced the ambiguous Square, Rectangle and One-Line layout choices with a direct Number of lines control from one to four.","Created exactly one editable text field for every requested line so users control line breaks before generation.","Started the text workflow with the practical two-line example Happy Birthday / Sophia.","Reordered font directions to Cursive Font, Serif Font and Mixed Font.","Added a Change fonts action that keeps the current composition and adds a new chronological font alternative after the first generation.","Added a collapsed Letter details prompt for optional instructions such as a heart above a letter or an extended terminal flourish.","Kept decorative instructions separate from exact line text and added a concise 240-character limit in preparation for safe API prompt injection.","Made every font card open a large preview gallery with previous, next and Use this font controls.","Applied the same large, navigable preview gallery to all six image-style cards.","Kept generated alternatives in the existing Versions rail and retained Add to page for the selected preview." ]},
  {version:"v0.86",title:"Optional visual layer validation and responsive cutout tools",changes:["Changed cut-safety measurement from a 2 mm threshold to a strict 1 mm threshold for enclosed gaps, detached islands and structurally thin regions.","Stopped SVG export from automatically initiating a safety scan for users who have not requested one.","Added an optional Validate the Layers action beneath the layer list with a plain-language explanation before scanning begins.","Kept validation advisory rather than blocking and added material-to-mat guidance for very small pieces and nearby cut lines.","Stored the project's validation preference so warnings remain consistently optional after saving and reopening.","Added an image preview to each Cut safety issue dialog and overlaid detected regions in the inverse of the cutout colour.","Softened the export warning language and retained a clear Continue and export SVG choice.","Added independent Edit Cutout undo and redo handling so Ctrl+Z and Ctrl+Shift+Z no longer modify the canvas behind the modal.","Added Ctrl+Shift+Z redo support to the main canvas, Edit Image and Background Removal histories wherever Ctrl+Z is supported.","Moved live Edit Cutout pointer drawing out of the React render loop and into requestAnimationFrame updates for responsive high-frequency feedback.","Deferred expensive mask rendering until the pointer is released while keeping a live visual stroke during drawing.","Reduced point-spacing loss so curved brush gestures retain smoother trajectories.","Capped Edit Cutout brush size at 20% and expanded useful slider precision.","Added a live circular brush-size preview beside the slider.","Made the Fix the Edges cursor thinner, rounder, stable between pixels and visually bounded at high zoom.","Adjusted effective high-zoom brush coverage so the selection does not become excessively thick.","Removed Stroke controls from the second Edit Cutout tab and renamed it Fill Gaps.","Changed both Fill Gaps controls to 0.5 mm² increments through the first 5 mm², 1 mm² increments thereafter and a 30 mm² maximum." ]},
  {version:"v0.85",title:"Minimally invasive vector edit commits",changes:["Traced the post-edit distortion to Apply Edit rasterizing the entire SVG, reducing it to approximately 96 pixels per centimetre and running aggressive VTracer simplification over every untouched curve.","Removed physical-size-based downsampling from the Edit Cutout commit path.","Removed the second silhouette rebuild and aggressive VTracer approximation after Bridge, Eraser and Fix the Edges operations.","Made Apply Edit trace the edited alpha mask at its natural high resolution with low-tolerance curve fitting and explicit corner preservation.","Applied the same protected high-resolution path to the manual Smooth action inside Edit Cutout.","Kept the result as one welded Cricut-compatible compound path instead of appending overlapping edit fragments that would require a separate Weld operation in Cricut Design Space.","Preserved transparent frame padding and fill-only cut geometry after edited SVG generation." ]},
  {version:"v0.84",title:"Verified generated PNG insertion",changes:["Reproduced Add to page against the authenticated live editor instead of relying on the success notification alone.","Identified a production-only name collision between the browser File constructor and the imported File icon component.","Made generated artwork explicitly use the browser's native window.File constructor before entering the canvas importer.","Kept the generated preview open and exposed a concrete error whenever the canvas does not accept exactly one new layer.","Rebuilt and republished the corrected import path for a second live end-to-end verification." ]},
  {version:"v0.83",title:"Faithful transparent artwork tracing and reliable generated imports",changes:["Fixed Add to page silently rejecting generated PNG files when the hosting server returned a generic MIME type.","Forced generated previews through the verified PNG import route and surfaced the exact loading failure when an import cannot complete.","Detected artwork that already contains a transparent canvas before starting cutout conversion.","Stopped transparent text and illustration PNGs from being destructively passed through automatic background removal, feathering and silhouette rebuilding.","Stopped tying vector trace resolution to the layer's physical centimetre width, which had reduced the supplied 1772 px text artwork to approximately 957 px before tracing.","Traced transparent alpha artwork at its native resolution, with controlled upscaling only for genuinely small sources.","Reduced curve optimisation tolerance to preserve clean typographic corners and intentional contour detail.","Removed the artificial 1.1 px dark SVG stroke that expanded cut boundaries and created visible protrusions around otherwise smooth artwork.","Retained transparent padding around the traced contour so no top, right, bottom or left edge can touch the SVG frame." ]},
  {version:"v0.82",title:"Purposeful Add New proportions and clean text previews",changes:["Rebuilt Add New around content-sized dialogs instead of stretching controls across a wide modal.","Removed the empty side gutters around initial choices and made both actions taller, balanced cards.","Applied the same compact card system to the Create your own image Text and Image choice screen.","Reorganized both creation studios around a compact prompt-and-example row instead of a page-wide example banner.","Changed all six image-style cards to near-square proportions in a strict two-row, three-column grid.","Replaced filtered gold text artwork with dedicated broken-black PNG assets on broken-white preview surfaces.","Removed the CSS filter that rendered semi-transparent source pixels as solid black blocks.","Reduced Font and Layout controls to compact, legible three-column cards with tightly fitted artwork.","Made the Versions rail continuously fill the creation workspace height.","Made Add to page import the exact previewed PNG directly and report loading failures instead of silently doing nothing." ]},
  {version:"v0.81",title:"Compact and functional creation menus",changes:["Reduced the width of Add New and every nested creation view to remove excessive horizontal whitespace.","Rebuilt the initial Add New choices as compact centered cards with tightly fitted reference artwork.","Removed Gold paper and Colored paper from Cake topper as text.","Standardized generated text presentation on broken-white preview surfaces with broken-black lettering.","Made Add to page convert simulated text artwork into true broken-black PNG pixels instead of only applying a visual filter.","Compacted Font and Layout choices into balanced three-column thumbnail cards.","Added a sixth Paper Cut image style generated from layered coloured cardstock.","Reflowed all six image styles into a consistent two-row, three-column grid.","Extended the Versions rail to match the complete creation form height while retaining chronological V1, V2 and later results.","Repaired Add to page asset loading with an explicit absolute application URL, response validation and a real PNG import path.","Kept generated-result lightbox interactions from closing the parent Add New dialog prematurely." ]},
  {version:"v0.80",title:"Visual AI creation studio simulation",changes:["Rebuilt every Add New creation menu around real supplied and generated visual examples.","Added the supplied gold and coloured paper photographs to the text material choices.","Added Mixed, Cursive and Serif font cards using generated transparent cake-topper examples.","Added Square, Rectangle and One-Line layout cards with exact three-line, two-line and single-line examples.","Replaced generic image-style swatches with generated Watercolor, Cartoon, Baby, Girly and 3D Storybook giraffe previews.","Refined Watercolor into a stronger hand-painted children's-book treatment, Cartoon into an original cinematic 3D animation look and Baby into simplified flat colour blocks.","Added an independent White sticker offset toggle to the image workflow in preparation for prompt injection.","Added a working Create image simulation that records chronological V1, V2 and later results in a right-side version rail.","Added a large generated-result preview with Add to page, allowing simulated AI results to enter the real editor canvas immediately.","Kept the future API boundary explicit while making the complete user journey testable with prepared local assets." ]},
  {version:"v0.79",title:"Guided Add New and AI creation menus",changes:["Changed Add New from an immediate file picker into a clear choice between creating artwork and uploading from the computer.","Added separate Cake topper as text and Cake topper as image creation forms in a navigable popup.","Added the supplied Happy Birthday Sophia and animals with balloons artwork as large prompt examples.","Added text prompts for the topper wording and image description with Happy Birthday Sophia and Cute giraffe placeholders.","Added selectable Gold paper and Colored paper treatments for text-based toppers.","Added selectable Watercolor, Cartoon, Paper cut, Elegant, Minimal and Glitter-look styles for image-based toppers.","Prepared a visibly disabled Create image action so the menus can be reviewed before the API is connected.","Preserved the existing multi-file JPG, PNG, SVG and WebP upload flow behind Upload from your computer." ]},
  {version:"v0.78",title:"True vector preview in Edit Cutout",changes:["Stopped Edit Cutout from automatically rasterizing an untouched SVG approximately 80 milliseconds after the editor opens.","Kept the original scalable SVG as the active preview until a pixel-based editing operation actually requires raster rendering.","Preserved smooth filled contours and crisp non-scaling edge strokes throughout Edit Cutout zooming.","Prevented high zoom levels from enlarging a low-resolution canvas preview into visible square pixels." ]},
  {version:"v0.77",title:"Structural thin-region safety analysis",changes:["Stopped treating every narrow horizontal or vertical scanline as an independent cut defect.","Grouped neighboring narrow samples into single physical regions so one thin feature is reported once instead of dozens or hundreds of times.","Ignored short-lived narrow samples at smooth outer tips and rounded contour ends that do not continue far enough to represent a fragile structure.","Required a sub-2 mm region to continue for at least 2 mm before raising a structural thinness warning.","Kept detection active for genuinely long thin artwork such as skis, poles, strings and narrow connecting bridges.","Changed warning wording from narrow cross-sections to structurally thin regions so the reported number describes actionable areas." ]},
  {version:"v0.76",title:"Safe cutout frames, actionable warnings and project session history",changes:["Added transparent breathing room around every VTracer cutout so paths and strokes cannot touch or be clipped by the SVG viewBox on the top, right, bottom or left edge.","Replaced generic cut-safety warnings with measured details including narrow-section counts, approximate minimum width, detached-island counts and enclosed-gap counts.","Changed vector Quick Fix from contour simplification alone into a real 1.1 mm protective expansion followed by smoothing and a fresh safety measurement.","Made Quick Fix report the exact remaining reason when an automatic repair cannot clear a warning.","Added a project-level Session Log that records layer selections, additions, removals, geometry changes, type changes, visibility changes, operation counts, warnings and editor result messages in chronological order.","Saved and restored Session Log entries with each cloud project.","Replaced the 150 DPI output label with a Session Log button and added a development-log-style history popup with Copy All." ]},
  {version:"v0.75",title:"Crop-safe background removal and aligned layer separation",changes:["Stopped Background Removal from reopening an older pre-removal source when a crop or image edit was applied afterward.","Made repeated Background Removal reuse earlier settings only when the removal is still the layer's current operation.","Preserved the current cropped source and its mapped canvas geometry when applying Default Background Removal after Edit Image.","Updated preset results with their true natural pixel dimensions after transparent trimming.","Derived separated-layer bounds from shared full-resolution pixel edges instead of independently rounded preview percentages.","Applied each connected-component mask in the same full-resolution coordinate system as its source crop, preventing shifted masks and clipped artwork edges."]},
  {version:"v0.74",title:"Black-pixel preservation and full-resolution image return",changes:["Fixed the edge-restoration fallback that incorrectly classified pure black RGB pixels as missing image data.","Kept every opaque source colour—including absolute black—unchanged through Edge Smooth and Advanced Background Removal.","Restricted white fallback pixels to genuinely transparent source coordinates created by outward edge expansion.","Updated the layer's natural pixel dimensions after applying Advanced Background Removal.","Reset stale Edit Image fit dimensions, zoom and pan when returning from Advanced Background Removal.","Made the first Edit Image tab reload the newly processed full-resolution source instead of retaining its previous preview scale." ]},
  {version:"v0.73",title:"Reliable cropped refinement and protected image detail",changes:["Moved the tiled Canson texture behind the editor grid so grid lines remain visible.","Made Advanced Background Removal consume the current Edit Image crop and erase result instead of reopening the uncropped source.","Mapped cropped image geometry into the background-removal result without jumping or restoring removed canvas space.","Rebuilt Optimize Alpha as a non-destructive cleanup that preserves antialiased contours and thin artwork details.","Reduced alpha cleanup to genuinely microscopic detached speckles and pinholes instead of majority-filtering every edge.","Stopped Optimize Alpha from automatically switching the preview into the black alpha-mask view.","Changed automatic image-background sampling to the lightest available corner so artwork touching another corner cannot cause dark image details to be removed.","Applied the same protected corner selection to Default and Add Rim presets." ]},
  {version:"v0.72",title:"Crisp vector edges, safe refinement and clipboard import",changes:["Added White as the default Page Color while retaining all existing display-only paper choices.","Replaced the simulated Canson pattern with the supplied seamless paper texture and tiled it across the editor page.","Kept page color and texture out of PNG, PDF and SVG exports.","Added Ctrl+V image import from the system clipboard while preserving normal paste inside text fields.","Kept SVG non-scaling strokes intact in the main canvas and Edit Cutout instead of converting their preview behaviour.","Changed every applied Edit Cutout result into a traced SVG, including edits that did not use Fix the Edges.","Changed generated Stroke, updated Stroke, Fill Gaps and stroke recolouring results into SVG contours instead of stored raster masks.","Expanded negative Edge Refinement into transparent working space so a growing rim can no longer be clipped by the original image frame.","Expanded Edge Refinement from ±12 px to ±25 px.","Standardized background-removal results on an inside-only one-pixel antialiased edge that stays sharp without a fuzzy outside halo."]},
  {version:"v0.71",title:"Clean island separation, page colors and precise shape selection",changes:["Changed Separate as Layers from rectangular source cropping to true connected-component alpha masking.","Prevented pixels belonging to neighboring artwork from leaking into an extracted island's rectangular bounds.","Re-ran cut-safety analysis on each isolated component without unrelated fragments.","Stopped raster Quick Fix from adding another rim when the layer already contains an Add Rim operation.","Changed existing-rim Quick Fix to clean alpha and recheck safety without enlarging the artwork.","Added Page Color directly beneath Page Size in Page Setup.","Added Broken White, Warm White, Light Gray, Dark Gray and Canson Paper display options.","Kept page color and paper texture entirely editor-only so PDF, PNG and SVG exports remain unchanged.","Added rotation-aware alpha hit testing for native shape layers.","Prevented transparent corners inside both unselected and selected shape bounds from selecting or dragging the shape."]},
  {version:"v0.70",title:"White-safe edge refinement and easier fixes",changes:["Prevented Advanced Background Removal edge expansion from restoring transparent zero-RGB pixels as black.","Made newly added Edge Refinement pixels use their valid original colour when available and white otherwise.","Applied the same white-safe rule after Edge Smooth so smoothing cannot reintroduce black pixels.","Expanded the canvas warning control into a clearly labelled Fix! button.","Stopped Fix! pointer presses from reaching the selection frame, keeping the control stable and clickable."]},
  {version:"v0.69",title:"Accurate preset preview and source-pixel rims",changes:["Restored the current edited image preview on the left side of Apply Preset.","Resized preset cards so each reference image fits completely inside its button.","Moved every preset title and subtitle into two compact lines beneath its image.","Made Apply Preset apply the selected result and immediately close Edit Image.","Removed repeated edge-color stamping from Add Rim.","Changed rim generation to expand only the alpha mask while taking every new pixel from the same coordinate in the original image.","Kept white as the exclusive fallback whenever the original image contains no usable pixel at a new rim coordinate."]},
  {version:"v0.68",title:"Reliable image editing, presets and protective rims",changes:["Fixed the hidden Advanced Background Removal state that appeared after Separate as Layers closed Edit Image.","Made Separate as Layers use the currently cropped and edited image together with its corrected canvas geometry.","Cleared every related image and background modal state after separated layers are created.","Fixed background presets using the wrong selected layer history when Quick Fix targeted another layer.","Rebuilt Add Rim as a physical protective expansion that keeps available edge pixels and uses white—not black—as its only fallback color.","Expanded the layer frame with the rim so new pixels are not clipped.","Applied alpha cleanup, smoothing and fresh safety analysis after rim creation.","Made Quick Fix replace the prior background-removal result instead of stacking repeated rims.","Added Apply Preset as the third Edit Image tab.","Added vertically arranged visual Default, Add Rim and Black-and-White Text presets inside Edit Image.","Made in-window presets respect crop and erase work already visible in the editor.","Repositioned and resized Undo, Reset, Alpha and Optimize Alpha immediately beside the close button.","Improved the visible alpha-mask preview and stopped Optimize Alpha from silently changing the Alpha view toggle.","Made Advanced Background Removal wait for the current preview render before its Apply action is available.","Added global pointer release, cancellation and focus-loss cleanup for stuck marquee selection rectangles."]},
  {version:"v0.67",title:"Reliable Image on Shape selection",changes:["Kept Image on Shape selection mode in a persistent interaction reference so selecting another layer cannot silently cancel it.","Captured Layers-panel image clicks before normal layer selection, preventing the chosen source from merely becoming selected.","Added a visible canvas instruction and copy cursor while the editor is waiting for an image.","Kept Escape cancellation synchronized with both the visible mode and its interaction state."]},
  {version:"v0.66",title:"Editable Image on Shape",changes:["Renamed Image in Shape to Image on Shape and changed it from a file picker into a canvas-and-Layers selection workflow.","Restricted shape placement to regular raster image layers so cutouts, shapes and generated stroke layers cannot be selected accidentally.","Kept the chosen image at its existing canvas position and size while displaying only its intersection with the shape.","Moved the source image into an editable Image on Shape layer style instead of permanently flattening or discarding it.","Added an independent image frame for repositioning and proportionally resizing the image inside the shape.","Made the embedded image travel, scale and rotate naturally with its parent shape.","Added visibility and removal controls to the Image on Shape style.","Restored the original image layer at its previous position and dimensions when the style is removed.","Kept shape color changes independent from the embedded image so eyedropper-picked fills continue to work.","Added Escape and repeat-click cancellation for the image-selection workflow."]},
  {version:"v0.65",title:"Raster-aware warnings and embedded background editing",changes:["Realigned cut-safety triangles and added hover feedback that clearly identifies them as clickable controls.","Split warning actions by layer type: cutouts open Edit Cutout while raster images open Edit Image.","Added Quick Fix: Add Rim for raster warnings and connected it directly to the Add Rim background-removal preset.","Added Edit Image and Advanced Background Removal tabs inside the same image editor window.","Kept Undo, Reset, Alpha and Optimize Alpha available in the image editor header across both tabs.","Limited Separate as Layers to the standard Edit Image tab.","Made Stroke and Fill Gaps disable as complete, visually consistent groups when the selection is incompatible.","Restyled the Layers heading to match the Stroke and Fill Gaps panel hierarchy.","Removed built-in whitespace from generated shape SVG bounds.","Changed shape hit testing so transparent portions of a shape layer no longer select it."]},
  {version:"v0.64",title:"Actionable safety warnings and cutout workspace tabs",changes:["Made cut-safety warning icons clickable from both the canvas measurement label and Layers panel.","Added a Cut Safety dialog with the detected reason, Cancel, Edit Cutout and Quick Fix actions.","Added one-click contour cleanup and automatic safety re-analysis through Quick Fix.","Moved the Layers warning icon beneath the visibility control.","Added Bring to Front, Send to Back and Hide to the floating layer toolbar.","Added Cutout Edit and Stroke & Fill Gaps tabs to Edit Cutout.","Renamed Bridge and Erase to Add Brush and Eraser Brush and redesigned the tool grid.","Expanded the Fix the Edges control across both columns and made brush sizing substantially wider.","Moved Crop beneath Crop Canvas and compacted the panel to avoid unnecessary scrolling.","Added a visible contour to areas painted with Add Brush.","Rendered vector layers with scalable strokes on both the main canvas and Edit Cutout preview.","Loaded the signed-in Google profile picture into My Account and made outside clicks dismiss the panel.","Refreshed Page Setup, My Projects, Open and Overwrite icon treatments.","Removed unused horizontal padding around Background Removal and Make Cutout preview cards."]},
  {version:"v0.63",title:"Cut safety analysis and cutout presets",changes:["Added physical 2 mm cut-safety analysis for thin connections, tiny positive islands and tiny enclosed gaps.","Marked risky selections and Layers cards in red with a visible warning icon.","Added a critical confirmation before exporting risky SVG files.","Applied the same safety analysis to background-removed raster images and vector cutouts.","Raised Edit Cutout zoom to 1000% and made SVG preview strokes scale with the artwork for crisp inspection.","Changed Make Cutout into a visual preset dialog.","Added Smooth Cutout, Detailed Cutout and Advanced Cutout Edit workflows.","Added the supplied detailed and smooth cutout preview artwork.","Enlarged both Cutout and Remove Background preset dialogs for clearer preview comparison."]},
  {version:"v0.62",title:"Safer project transitions and editor footer tools",changes:["Rebuilt overwrite and project-transition dialogs with editor-scale typography and consistent spacing.","Made the main Save update only mutable project fields and added a safe identity fallback for older saved projects.","Added a New Project confirmation even when the current project is already saved.","Displayed Saved as a disabled action for clean projects, alongside Save As and OK.","Added Open saved projects beneath Choose an image on an empty canvas.","Exposed icon-only Open, Overwrite and Delete actions on collapsed project cards.","Moved Separate as Layers into the bottom action bar in both Edit Image and Edit Cutout.","Moved Smooth to the lower-left Edit Cutout action bar and relocated the image editor undo hint."]},
  {version:"v0.61",title:"Scale-stable contours and calmer project feedback",changes:["Added a dedicated Smooth action inside Edit Cutout for reducing excess contour points before Apply Edit.","Made repeated smoothing progressively stronger while preserving sharp direction changes.","Normalized tracing resolution against the layer's physical width so small and large designs receive consistent curve density.","Kept My Projects content cached and visible while fresh cloud data loads in the background.","Changed saving feedback to show Saving first, then Saved with a two-second countdown.","Allowed the saving notice to be dismissed without interrupting the background upload.","Rebuilt project cards with smaller typography, correctly fitted previews and downward-only expansion.","Gave the project list a stable viewport so expanding one project pushes later projects down instead of compressing its content."]},
  {version:"v0.60",title:"Reliable project saving and batch cutouts",changes:["Converted every compatible selected image into a Cricut-ready cutout in one operation.","Added Save Project and Save As Project directly inside My Projects.","Added a visible two-second saved confirmation with an immediate OK action.","Changed project rows into expandable cards so an accidental click no longer replaces the canvas.","Added compact project-wide thumbnails assembled from every visible layer.","Added individual layer previews, layer counts, project size and last-saved time to each project.","Added an explicit loading state while cloud projects are being retrieved.","Added save-before-open and save-before-new safeguards for canvases with unsaved work.","Added a separate overwrite confirmation before replacing an existing saved project."]},
  {version:"v0.59",title:"Cake Topper Maker identity and editor dev log",changes:["Renamed the editor workspace to Cake Topper Maker.","Turned the workspace version label into a clickable, scrollable development log.","Expanded releases into individual fixes and ordered the complete history newest first."]},
  {version:"v0.58",title:"Editor modal stability",changes:["Fixed the missing Layers icon import that crashed Edit Image and Edit Cutout when opened.","Rebuilt and validated both editor routes before deployment."]},
  {version:"v0.57",title:"Smooth Cutout v5 and island separation",changes:["Limited automatic empty-border trimming to PNG files; JPG files are left untouched.","Captured Chrome wheel events directly on the canvas so zoom no longer scrolls the document at the same time.","Kept cursor-anchored zoom correct across portrait, landscape and full-page modes.","Restored the dark contour after Fix the Edges modifies alpha pixels.","Moved edge re-vectorization to Apply Edit and run it only when an edge was actually fixed.","Added a dedicated, toggleable Crop mode to Edit Cutout.","Added Separate as Layers to both image and cutout editors.","Detected disconnected alpha islands and previewed every future layer in a different color.","Added explicit Cancel and Create Layers confirmation actions before replacing the source layer."]},
  {version:"v0.56",title:"Precision cutout editing feedback",changes:["Raised the main canvas maximum zoom to 700%.","Changed the Fix the Edges cursor from an oval SVG marker to a true circular overlay.","Displayed the selected physical alpha edge in red instead of painting the whole brush corridor.","Displayed the completed edge in green for one second before returning to its normal contour.","Added automatic PNG whitespace bounds detection when files enter the canvas."]},
  {version:"v0.55",title:"Cricut-optimized Smooth Cutout v4",changes:["Corrected VTracer spliceThreshold from 4 to its intended 45-degree curve split threshold.","Reduced thousands of tiny cutting movements by joining compatible curve runs.","Enabled the strongest SVG path cleanup and coordinate compaction.","Balanced curve simplification against preservation of long banner arcs and sharp corners."]},
  {version:"v0.54",title:"Google authentication repair",changes:["Added a cryptographically random nonce to Google One Tap.","Sent the SHA-256 nonce to Google and its original value to Supabase so validation succeeds.","Enabled the FedCM-compatible Google prompt flow."]},
  {version:"v0.53",title:"Visible sign-in diagnostics",changes:["Stopped silently swallowing Supabase authentication errors.","Added a persistent, readable sign-in error message to the landing page.","Required a real Supabase session before navigating to the protected editor."]},
  {version:"v0.52",title:"Landing-to-editor session flow",changes:["Changed every Open Editor call-to-action to check the current session.","Unauthenticated editor actions now open Google sign-in instead of bouncing through login=required.","Authenticated actions continue directly to /editor."]},
  {version:"v0.51",title:"Image clipping masks for shapes",changes:["Added Image in Shape for native vector shapes.","Allowed the placed image to be scaled and positioned while remaining clipped to its shape.","Added eyedrop color sampling for shape fills."]},
  {version:"v0.50",title:"Background history and geometry recovery",changes:["Reopened Advanced Background Removal from the last applied settings instead of starting over.","Remembered removed background colors for later edge expansion.","Restored original layer bounds when a background-removal step is removed.","Expanded layer bounds when edge refinement adds pixels outside the previous frame."]},
  {version:"v0.49",title:"Cutout interaction refinements",changes:["Added repeated-click cycling through overlapping layers.","Reset overlap cycling whenever the pointer moves.","Allowed crop handles in Edit Image to expand the canvas outward.","Made Edit Cutout tools toggleable and start with no active tool.","Strengthened trajectory-based Fix the Edges corrections."]},
  {version:"v0.48",title:"Background removal preset dialog",changes:["Replaced the background-removal chevron with a standalone visual preset dialog.","Added Default Image, Add Rim and Black-and-White Text removal presets.","Added 2 px feathering to image presets for softer Print Then Cut edges.","Reworked zoom controls with editable percentage, Center and Calibrate actions."]},
  {version:"v0.47",title:"Alpha cleanup and physical calibration",changes:["Added Optimize Alpha to remove tiny exterior islands and fill tiny interior holes.","Added adjustable Edge Smooth for reducing blade-path pixel noise.","Made 100% zoom respect saved physical screen calibration.","Added fine 0.1% calibration controls and one-direction ruler resizing."]},
  {version:"v0.46",title:"Page, selection and editing workflow",changes:["Added Page Setup with portrait, landscape and 100 × 100 cm full canvas modes.","Added Save, Save As and New Project as separate actions.","Changed marquee selection to hit visible pixels rather than empty layer bounds.","Added erase and lasso erase to Edit Image.","Added connected-area brush and multi-color eyedrop background removal.","Added grouped movement constraints and complete layer thumbnails."]},
  {version:"v0.45",title:"Landing page product story",changes:["Built the Ariana is ONE prompt-to-cake case study.","Redesigned product highlights around real Cricut tasks.","Added the technical terminal-style development history.","Fixed landing-page scrolling and editor navigation."]},
  {version:"v0.44",title:"Targeted contour repair",changes:["Added Fix the Edges for local contour correction.","Used the selected stroke endpoints and trajectory to preserve the intended curve.","Added popup zoom and pan plus a 400% editing zoom range.","Added grid visibility and compact background-removal controls."]},
];

export const editorDevLog:readonly EditorRelease[]=[...recent,...[...releaseLog].reverse().map(([version,title,text])=>({version,title,changes:[text]}))];
export const EDITOR_VERSION=recent[0].version;
